    /** Regroupe les catégories éparpillées vers celles proposées dans le menu Setup. */
    private val categoryAliases: Map<String, String> = mapOf(
        "Technologie" to "Tech",
        "Geographie" to "Géographie",
        "Art" to "Culture",
        "Champions League" to "Sport",
        "Football" to "Sport",
        "Formule 1" to "Sport",
        "Basket-ball" to "Sport",
        "Tennis" to "Sport",
        "Jeux Olympiques" to "Sport"
    )

    private fun normalizeKey(text: String): String =
        java.text.Normalizer.normalize(text.lowercase(), java.text.Normalizer.Form.NFD)
            .replace(Regex("\\p{Mn}+"), "")
            .replace(Regex("[^a-z0-9]+"), " ")
            .trim()

    private val questions: List<Question> by lazy {
        val seen = HashSet<String>()
        rawQuestions
            .map { q -> categoryAliases[q.category]?.let { q.copy(category = it) } ?: q }
            .filter { q -> q.answers.size >= 2 && q.correctIndex in q.answers.indices }
            .filter { q -> seen.add(normalizeKey(q.text)) }   // doublons exacts : on garde le premier
    }

    /**
     * Mélange l'ordre des réponses (sinon la bonne réponse est très souvent en A)
     * et recalcule correctIndex en conséquence.
     */
    private fun Question.withShuffledAnswers(): Question {
        if (answers.size < 2) return this
        val order = answers.indices.shuffled()
        return copy(answers = order.map { answers[it] }, correctIndex = order.indexOf(correctIndex))
    }

    /** Questions déjà posées pendant cette session d'app : évite les répétitions d'une partie à l'autre. */
    private val recentlyAsked = LinkedHashSet<String>()
    private const val RECENT_MEMORY = 1500

    private fun pickFresh(pool: List<Question>, count: Int): List<Question> {
        val fresh = pool.filter { it.text !in recentlyAsked }
        val picked = if (fresh.size >= count) fresh.take(count)
            else fresh + pool.filter { it.text in recentlyAsked }.take(count - fresh.size)
        picked.forEach { recentlyAsked.add(it.text) }
        while (recentlyAsked.size > RECENT_MEMORY) recentlyAsked.remove(recentlyAsked.first())
        return picked
    }

    /**
     * Tire UNE question fraîche d'une difficulté donnée (réponses mélangées).
     * Sert quand le joueur choisit une difficulté absente de la pile, ou utilise « Changer de question ».
     */
    fun drawOne(categories: List<String>, difficulty: Difficulty, excludeTexts: Set<String>): Question? {
        val pool = (if (categories.contains("ALL")) questions else questions.filter { it.category in categories })
            .filter { it.difficulty == difficulty && it.text !in excludeTexts }
        if (pool.isEmpty()) return null
        return pickFresh(pool.shuffled(), 1).firstOrNull()?.withShuffledAnswers()
    }

    /** Nombre de questions par catégorie (pour l'écran de configuration). */
    fun countByCategory(): Map<String, Int> = questions.groupingBy { it.category }.eachCount()

    /** Nombre total de questions jouables. */
    fun totalCount(): Int = questions.size

    fun getByCategory(category: String): List<Question> {
        if (category == "ALL") return questions.shuffled()
        return questions.filter { q: Question -> q.category == category }.shuffled()
    }

    fun getByDifficulty(difficulty: Difficulty): List<Question> {
        return questions.filter { q: Question -> q.difficulty == difficulty }.shuffled()
    }

    fun getForGame(
        totalQuestions: Int,
        categories: List<String>,
        difficulty: Difficulty?
    ): List<Question> {
        var pool: List<Question> = if (categories.contains("ALL")) questions
            else questions.filter { q: Question -> q.category in categories }
        if (difficulty != null) {
            pool = pool.filter { q: Question -> q.difficulty == difficulty }
        }
        return pickFresh(pool.shuffled(), totalQuestions).map { it.withShuffledAnswers() }
    }

    fun getForPlayerLevel(
        totalQuestions: Int,
        playerLevel: Int,
        categories: List<String> = listOf("ALL")
    ): List<Question> {
        // Legacy — redirige vers getRandomMix
        return getRandomMix(totalQuestions, categories)
    }

    /**
     * Mix aléatoire de TOUTES les difficultés — utilisé quand il n'y a plus de niveau joueur.
     * Distribution : ~30% EASY, ~35% MEDIUM, ~25% HARD, ~10% EXPERT
     */
    fun getRandomMix(
        totalQuestions: Int,
        categories: List<String> = listOf("ALL")
    ): List<Question> {
        val pool: List<Question> = if (categories.contains("ALL")) questions
            else questions.filter { q: Question -> q.category in categories }

        // On privilégie les questions pas encore vues pendant cette session
        val freshPool = pool.filter { it.text !in recentlyAsked }.let { if (it.size >= totalQuestions) it else pool }
        val easyPool = freshPool.filter { it.difficulty == Difficulty.EASY }.shuffled()
        val mediumPool = freshPool.filter { it.difficulty == Difficulty.MEDIUM }.shuffled()
        val hardPool = freshPool.filter { it.difficulty == Difficulty.HARD }.shuffled()
        val expertPool = freshPool.filter { it.difficulty == Difficulty.EXPERT }.shuffled()

        val easyCount = (totalQuestions * 0.30).toInt()
        val mediumCount = (totalQuestions * 0.35).toInt()
        val hardCount = (totalQuestions * 0.25).toInt()
        val expertCount = totalQuestions - easyCount - mediumCount - hardCount

        val selected = mutableListOf<Question>()
        selected.addAll(easyPool.take(easyCount))
        selected.addAll(mediumPool.take(mediumCount))
        selected.addAll(hardPool.take(hardCount))
        selected.addAll(expertPool.take(expertCount))

        // Si pas assez de questions dans certaines difficultés, compléter avec le pool global
        if (selected.size < totalQuestions) {
            val remaining = pool.filter { it !in selected }.shuffled()
            selected.addAll(remaining.take(totalQuestions - selected.size))
        }

        selected.forEach { recentlyAsked.add(it.text) }
        while (recentlyAsked.size > RECENT_MEMORY) recentlyAsked.remove(recentlyAsked.first())
        return selected.shuffled().map { it.withShuffledAnswers() }
    }

    val categories: List<String> = listOf(
        "ALL", "Science", "Histoire", "Géographie", "Culture", "Tech", "Sport",
        "Cinéma", "Gastronomie", "Musique", "Mathématiques", "Philosophie",
        "Mythologie", "Sciences Humaines", "Économie", "Nature", "Politique",
        "Littérature"
    )
}
